def clip_polygon(polygon, signed_distance):
    if not polygon: return []
    result=[];previous=polygon[-1];prev_dist=signed_distance(previous)
    for point in polygon:
        distance=signed_distance(point)
        if (distance>=0)!=(prev_dist>=0):
            amount=prev_dist/(prev_dist-distance);result.append(tuple(a+amount*(b-a) for a,b in zip(previous,point)))
        if distance>=0: result.append(point)
        previous=point;prev_dist=distance
    return result

def area2(poly):
    return sum(poly[index][0]*poly[(index+1)%len(poly)][1]-poly[index][1]*poly[(index+1)%len(poly)][0] for index in range(len(poly)))

def intersect_polygons(poly, boundary):
    orientation=1 if area2(boundary)>0 else -1
    for index,first in enumerate(boundary):
        second=boundary[(index+1)%len(boundary)]
        poly=clip_polygon(poly,lambda point: orientation*((second[0]-first[0])*(point[1]-first[1])-(second[1]-first[1])*(point[0]-first[0])))
        if len(poly)<3: return []
    return poly

